import { Block, Text } from "@prototyp/skeletor";
import {
  type RoomInterface,
  StateEventType,
  type UserProfile,
} from "@unomed/react-native-matrix-sdk";
import { useAtomValue } from "jotai";
import { CallAtoms } from "modules/call/jotai";
import { CallOverlayService } from "modules/call/service/CallOverlayService";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { resetToRoom } from "modules/navigation/utils";
import { NetworkAtoms } from "modules/network/jotai";
import { useRoomInfo } from "modules/room/hooks";
import { RoomService } from "modules/room/service/RoomService";
import { type FC, useEffect, useState } from "react";
import { Image, Share, StyleSheet } from "react-native";
import { Button, Loading } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

interface Props {
  userProfile: UserProfile;
}

export const ActionButtons: FC<Props> = ({ userProfile }) => {
  const [loading, setLoading] = useState(false);
  const [existingDirectRoom, setExistingDirectRoom] = useState<
    RoomInterface | undefined
  >(undefined);
  const hasActiveCall = useAtomValue(CallAtoms.hasActiveCall);
  const isOffline = useAtomValue(NetworkAtoms.isOffline);
  const roomInfo = useRoomInfo(existingDirectRoom);
  const hasPowerLevelToCall = existingDirectRoom
    ? (roomInfo?.powerLevels?.canOwnUserSendState(StateEventType.CallMember) ??
      false)
    : true;

  useEffect(() => {
    RoomService.getExistingDirectRoom(userProfile.userId).then((roomId) => {
      if (!roomId) return;
      const room = MatrixCore.instance?.getRoom(roomId);
      setExistingDirectRoom(room ?? undefined);
    });
  }, [userProfile.userId]);

  const handleShare = () => {
    Share.share({
      message:
        "Hey, I'm using Cloak and Dagger! Download it now: https://cloak.app",
    });
    return;
  };

  const handleStartChat = async () => {
    if (!userProfile) return;

    try {
      setLoading(true);
      const roomId = await RoomService.getOrCreateDirectRoom(
        userProfile.userId,
      );

      setTimeout(() => {
        resetToRoom(roomId);
      }, 300);
    } catch (error) {
      console.error("Failed to start chat:", error);
      offlineToastHelper("Failed to start chat");
    } finally {
      setLoading(false);
    }
  };

  const handleCall = async () => {
    if (!userProfile) return;

    if (hasActiveCall) {
      offlineToastHelper("You are already in a call");
      return;
    }

    if (isOffline) {
      offlineToastHelper("No internet connection");
      return;
    }

    try {
      setLoading(true);
      const roomId = await RoomService.getOrCreateDirectRoom(
        userProfile.userId,
      );

      const room = MatrixCore.instance?.getRoom(roomId);
      const roomName = room?.displayName();

      setTimeout(() => {
        resetToRoom(roomId);
        CallOverlayService.openCall(roomId, roomName);
      }, 300);
    } catch (error) {
      console.error("Failed to start call:", error);
      offlineToastHelper("Failed to start call");
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      {loading && <Loading />}
      <Block
        flexDirection="row"
        gap={8}
        margins={{ marginTop: 32, marginBottom: 20 }}
      >
        <Button.Wrapper style={styles.button} onPress={handleStartChat}>
          <Block
            width="100%"
            align="center"
            justify="center"
            paddings={12}
            background={Colors.white10}
            border={{ borderRadius: 16 }}
            gap={8}
          >
            <Image
              source={require("assets/icons/chat-cloud.png")}
              tintColor={Colors.white}
            />

            <Text
              size={TextSize.small}
              font="InstrumentSans-Medium"
              color={Colors.white}
            >
              Message
            </Text>
          </Block>
        </Button.Wrapper>
        {hasPowerLevelToCall && (
          <Button.Wrapper
            style={styles.button}
            disabled={hasActiveCall}
            onPress={handleCall}
          >
            <Block
              width="100%"
              align="center"
              justify="center"
              paddings={12}
              background={Colors.white10}
              border={{ borderRadius: 16 }}
              gap={8}
            >
              <Image
                source={require("assets/icons/phone-call.png")}
                tintColor={Colors.white}
              />

              <Text
                size={TextSize.small}
                font="InstrumentSans-Medium"
                color={Colors.white}
              >
                Call
              </Text>
            </Block>
          </Button.Wrapper>
        )}
        <Button.Wrapper style={styles.button} onPress={handleShare}>
          <Block
            width="100%"
            align="center"
            justify="center"
            paddings={12}
            background={Colors.white10}
            border={{ borderRadius: 16 }}
            gap={8}
          >
            <Image
              source={require("assets/icons/upload-simple-large.png")}
              tintColor={Colors.white}
              style={styles.buttonIcon}
              width={24}
              height={24}
            />

            <Text
              size={TextSize.small}
              font="InstrumentSans-Medium"
              color={Colors.white}
            >
              Share
            </Text>
          </Block>
        </Button.Wrapper>
      </Block>
    </>
  );
};

const styles = StyleSheet.create({
  button: {
    flex: 1,
  },
  buttonIcon: {
    width: 24,
    height: 24,
  },
});

import { Block, Text } from "@prototyp/skeletor";
import {
  type RoomInterface,
  type RoomMember,
  RoomNotificationMode,
} from "@unomed/react-native-matrix-sdk";
import { useAtom, useAtomValue } from "jotai";
import { CallAtoms } from "modules/call/jotai";
import { CallOverlayService } from "modules/call/service/CallOverlayService";
import { NavigationContainerRef } from "modules/navigation/const";
import { NetworkAtoms } from "modules/network/jotai";
import { RoomAtoms } from "modules/room/jotai";
import { RoomService } from "modules/room/service/RoomService";
import { type FC, useState } from "react";
import { Image, Share, StyleSheet } from "react-native";
import { Button } from "shared/components";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

interface Props {
  room: RoomInterface;
  members: RoomMember[];
  hasPowerLevelToCall?: boolean;
  canInvite?: boolean;
}

export const ActionButtons: FC<Props> = ({
  room,
  members,
  hasPowerLevelToCall = false,
  canInvite = false,
}) => {
  const [isMuting, setIsMuting] = useState(false);
  const [roomNotificationMode, setRoomNotificationMode] = useAtom(
    RoomAtoms.roomNotificationMode,
  );
  const isMuted = roomNotificationMode === RoomNotificationMode.Mute;
  const isOffline = useAtomValue(NetworkAtoms.isOffline);
  const hasActiveCall = useAtomValue(CallAtoms.hasActiveCall);

  const handleToggleMute = async () => {
    setIsMuting(true);
    try {
      await RoomService.setRoomMuted(room.id(), !isMuted);
      setRoomNotificationMode(!isMuted ? RoomNotificationMode.Mute : null);
    } catch (error) {
      offlineToastHelper("Failed to toggle mute");
      console.error("Failed to toggle mute:", error);
    } finally {
      setIsMuting(false);
    }
  };

  const handleShare = () => {
    Share.share({
      message:
        "Hey, I'm using Cloak and Dagger! Download it now: https://cloak.app",
    });
  };

  const handleStartCall = () => {
    if (!hasPowerLevelToCall) return;

    if (isOffline) {
      offlineToastHelper("No internet connection");
      return;
    }

    CallOverlayService.openCall(room.id(), room.displayName());
  };

  const handleInvitePeople = () => {
    NavigationContainerRef.navigate("invitePeople", {
      roomId: room.id(),
      members,
    });
  };

  return (
    <Block
      flexDirection="row"
      gap={8}
      margins={{ marginTop: 32, marginBottom: 20 }}
    >
      {hasPowerLevelToCall && (
        <Button.Wrapper
          style={styles.button}
          onPress={handleStartCall}
          disabled={hasActiveCall}
        >
          <Block
            width="100%"
            align="center"
            justify="center"
            paddings={12}
            background={Colors.white10}
            border={{ borderRadius: 16 }}
            gap={8}
          >
            <Image
              source={require("assets/icons/phone-call.png")}
              tintColor={Colors.white}
            />

            <Text
              size={TextSize.small}
              font="InstrumentSans-Medium"
              color={Colors.white}
            >
              Call
            </Text>
          </Block>
        </Button.Wrapper>
      )}
      <Button.Wrapper
        style={styles.button}
        onPress={handleToggleMute}
        disabled={isMuting}
      >
        <Block
          width="100%"
          align="center"
          justify="center"
          paddings={12}
          background={Colors.white10}
          border={{ borderRadius: 16 }}
          gap={8}
        >
          <Image
            source={
              isMuted
                ? require("assets/icons/bell-slash.png")
                : require("assets/icons/bell.png")
            }
            tintColor={Colors.white}
          />

          <Text
            size={TextSize.small}
            font="InstrumentSans-Medium"
            color={Colors.white}
          >
            {isMuted ? "Unmute" : "Mute"}
          </Text>
        </Block>
      </Button.Wrapper>
      <Button.Wrapper style={styles.button} onPress={handleShare}>
        <Block
          width="100%"
          align="center"
          justify="center"
          paddings={12}
          background={Colors.white10}
          border={{ borderRadius: 16 }}
          gap={8}
        >
          <Image
            source={require("assets/icons/upload-simple-large.png")}
            tintColor={Colors.white}
            style={styles.buttonIcon}
            width={24}
            height={24}
          />

          <Text
            size={TextSize.small}
            font="InstrumentSans-Medium"
            color={Colors.white}
          >
            Share
          </Text>
        </Block>
      </Button.Wrapper>
      {canInvite && (
        <Button.Wrapper style={styles.button} onPress={handleInvitePeople}>
          <Block
            width="100%"
            align="center"
            justify="center"
            paddings={12}
            background={Colors.white10}
            border={{ borderRadius: 16 }}
            gap={8}
          >
            <Image
              source={require("assets/icons/user-plus.png")}
              tintColor={Colors.white}
            />

            <Text
              size={TextSize.small}
              font="InstrumentSans-Medium"
              color={Colors.white}
            >
              Invite
            </Text>
          </Block>
        </Button.Wrapper>
      )}
    </Block>
  );
};

const styles = StyleSheet.create({
  button: {
    flex: 1,
  },
  buttonIcon: {
    width: 24,
    height: 24,
  },
});

